    '★조건 커버리지와 결정 커버리지는 서로 포함관계가 없다★. 조건 100%인데 결정 50%일 수 있고, 그 반대도 가능하다.',
    '조건/결정 → 조건과 결정을 모두 포함. MC/DC → 조건/결정을 포함. 다중 조건 → MC/DC 를 포함.',
    'MC/DC 는 조건이 n 개일 때 최소 ★n+1★ 개 케이스로 달성 가능해 다중 조건(2의 n승)보다 실용적이다.'
