  { s:'s8', t:'테스트 프로세스', d:2, q:'테스트 환경 구축은 테스트 분석 및 설계 단계의 활동이다.', a:false, e:'테스트 환경 구축은 테스트 데이터 준비와 함께 테스트 구현 및 실행 단계의 활동이다.' },
  { s:'s8', t:'테스트 프로세스', d:1, q:'테스트웨어를 형상 관리 저장소에 보관하는 것은 테스트 종료 활동에 포함된다.', a:true, e:'종료 활동은 미결 결함 이관, 요약 보고서 작성, 테스트웨어 보관, 교훈 회고로 이루어진다.' },
  { s:'s8', t:'테스트 문서·케이스', d:3, q:'3점 추정에서 낙관 2, 최빈 5, 비관 14 이면 기대값은 6 이다.', a:true, e:'(2 + 4 x 5 + 14) / 6 = 36 / 6 = 6 이다.' },
  { s:'s8', t:'결함 관리·지표', d:2, q:'TPI NEXT 는 TMMi 처럼 5단계 성숙도 레벨 구조를 갖는 모델이다.', a:false, e:'5단계 성숙도 레벨 구조는 TMMi 의 특징이다. TPI NEXT 는 핵심 영역별 성숙도 매트릭스로 진단한다.' }
